const PRODUCTS = Array.isArray(DATA)
  ? DATA.filter(product => product && typeof product.descricao === 'string' && product.descricao.trim())
  : [];

const PLAN_GROUPS = {
  mobile: [
    'TIM CONTROLE', 'TIM CONTROLE PLUS', 'TIM CONTROLE PREMIUM',
    'TIM CONTROLE SMART', 'TIM CONTROLE REDES SOCIAIS',
    'TIM BLACK', 'TIM BLACK PLUS', 'TIM BLACK PREMIUM',
    'TIM BLACK A (15GB)', 'TIM BLACK B (20GB)', 'TIM BLACK C (25GB)',
    'TIM BLACK C ULTRA', 'TIM BLACK FAMÍLIA', 'TIM BLACK FAMÍLIA A ONE',
    'TIM BLACK FAMÍLIA PLUS', 'TIM BLACK FAMÍLIA PREMIUM',
    'TIM BLACK FAMÍLIA C ONE', 'TIM BLACK FAMÍLIA VIP',
  ],
  fibra: [
    'TIM Fibra 300M 24', 'TIM Fibra 400M 24', 'TIM Fibra 500M 24 - 2',
    'TIM Fibra 600M 24 - 2', 'TIM Fibra 600M P 24 - 2', 'TIM Fibra 600M M 24 - 2',
    'TIM Fibra 600M GP 25', 'TIM Fibra 1GB 24', 'TIM Fibra 1GB P 24',
    'TIM Fibra 1GB M 24', 'TIM Fibra 2GB 24',
  ],
};

// Inclui automaticamente planos novos encontrados na planilha. Isso mantém
// o site atualizado mesmo quando a TIM altera o nome ou adiciona uma oferta.
const discoveredPlans = new Set(
  PRODUCTS.flatMap(product => Object.keys(product.planos || {})),
);
Object.keys(PLAN_GROUPS).forEach(group => {
  PLAN_GROUPS[group] = PLAN_GROUPS[group].filter(plan => discoveredPlans.has(plan));
});
[...discoveredPlans]
  .sort((a, b) => a.localeCompare(b, 'pt-BR'))
  .forEach(plan => {
    const group = /FIBRA|ULTRAFIBRA/i.test(plan) ? 'fibra' : 'mobile';
    if (!PLAN_GROUPS[group].includes(plan)) PLAN_GROUPS[group].push(plan);
  });

/** Preços sem fidelização (campos diretos do objeto produto) */
const NONFID = [
  { label: 'PRÉ (Balcão)',      field: 'pre',              desc: 'Preço de prateleira, sem plano' },
  { label: 'Base Faturamento',  field: 'base_retail',      desc: 'Preço base de faturamento retail' },
  { label: 'Controle Não Fid.', field: 'controle_nao_fid', desc: 'Plano Controle sem fidelização' },
  { label: 'Pós Não Fid.',      field: 'pos_nao_fid',      desc: 'Pós-pago sem fidelização' },
];
const NONFID_FIELD = Object.fromEntries(NONFID.map(n => [n.label, n.field]));

/** Lista achatada de todos os planos fidelizados, na ordem dos grupos */
const ALL_FIDELIZED_PLANS = [...PLAN_GROUPS.mobile, ...PLAN_GROUPS.fibra];


